using Avalonia;
using Avalonia.Controls;
using Avalonia.Layout;
using Avalonia.Media;
using System.Diagnostics;
using System.Text.Json;
namespace ProjectDesk;

public sealed class AiChatWindow : Window {
 private readonly AiSettingsStore _store;private readonly IMcpSecrets _secrets;private readonly ProjectSession _session;private readonly Func<int[]> _selected;private readonly Action _refresh;private readonly Func<AiProviderClient> _client;private readonly Action<Uri> _openWebsite;
 private readonly ComboBox _provider=new(){Name="AiProvider",MinWidth=260};private readonly TextBlock _status=new(){Text="Choose a connection and enter a question.",TextWrapping=TextWrapping.Wrap,Foreground=DesignTokens.Secondary};private readonly TextBox _question=new(){Name="AiQuestion",AcceptsReturn=true,MinHeight=80,MaxHeight=160,Watermark="Ask about your plan, review risks, or draft tasks…"};private readonly CheckBox _include=new(){Name="AiIncludeTasks",Content="Include selected tasks",IsChecked=false};private readonly StackPanel _messages=new(){Spacing=12};private readonly ScrollViewer _scroll;private readonly WrapPanel _actions=new();private readonly Button _cancel=new(){Content="Cancel Request",IsVisible=false};private readonly ProgressBar _progress=new(){Height=3,IsIndeterminate=true,IsVisible=false};private readonly List<AiMessage> _history=[];private readonly McpProjectRevision _revision=new();
 private CancellationTokenSource? _operation;private TaskCompletionSource? _idle;private bool _closing;private string? _lastReply,_replyRevision;
 public AiChatWindow(AiSettingsStore store,IMcpSecrets secrets,ProjectSession session,Func<int[]> selected,Action refresh,Func<AiProviderClient>? client=null,Action<Uri>? openWebsite=null){_store=store;_secrets=secrets;_session=session;_selected=selected;_refresh=refresh;_client=client??(()=>new(secrets));_openWebsite=openWebsite??(url=>Process.Start(new ProcessStartInfo(url.AbsoluteUri){UseShellExecute=true}));Title="Planora AI";Width=970;Height=790;MinWidth=720;MinHeight=560;WindowStartupLocation=WindowStartupLocation.CenterOwner;
  var root=new DockPanel{Margin=new Thickness(20)};var header=new StackPanel{Spacing=10};var title=new StackPanel{Orientation=Orientation.Horizontal,Spacing=10};title.Children.Add(new BrandMark{Width=34,Height=34});title.Children.Add(new TextBlock{Text="Planora AI",FontSize=24,FontWeight=FontWeight.SemiBold,VerticalAlignment=VerticalAlignment.Center});header.Children.Add(title);header.Children.Add(new TextBlock{Text="Discuss your plan with ChatGPT or Claude. Review any task draft before adding it.",TextWrapping=TextWrapping.Wrap,Foreground=DesignTokens.Secondary});var connections=new WrapPanel();connections.Children.Add(_provider);var setup=new Button{Content="Connection Settings",Margin=new Thickness(8,0,0,0)};setup.Click+=async(_,_)=>await Perform(EditConnection);connections.Children.Add(setup);header.Children.Add(connections);header.Children.Add(_status);header.Children.Add(_progress);DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
  var composer=new StackPanel{Spacing=10,Margin=new Thickness(0,14,0,0)};composer.Children.Add(_include);composer.Children.Add(_question);void Action(string text,Func<Task> action){var button=new Button{Content=text,Margin=new Thickness(0,0,8,5)};if(text=="Review and Send")button.Classes.Add("primary");button.Click+=async(_,_)=>await Perform(action);_actions.Children.Add(button);}Action("Review and Send",Send);Action("New Chat",()=>{Clear();_question.Text="";_status.Text="New chat ready.";return Task.CompletedTask;});Action("Import Task Draft",Import);Action("Paste Web Answer",PasteAnswer);Action("Copy Answer",CopyAnswer);_cancel.Click+=(_,_)=>_operation?.Cancel();_actions.Children.Add(_cancel);composer.Children.Add(_actions);var close=new Button{Content="Close",HorizontalAlignment=HorizontalAlignment.Right};close.Click+=(_,_)=>Close();composer.Children.Add(close);DockPanel.SetDock(composer,Dock.Bottom);root.Children.Add(composer);_scroll=new ScrollViewer{Content=_messages,Margin=new Thickness(0,12,0,0)};root.Children.Add(_scroll);Content=root;
  Reload(AiProvider.OpenAI);_provider.SelectionChanged+=(_,_)=>{if(_provider.SelectedItem is not AiConnectionProfile)return;Clear();_status.Text=Profile.Mode==AiConnectionMode.Browser?"Web handoff: review/copy the prompt, paste it in your browser, then paste the answer here.":Profile.Mode==AiConnectionMode.CodexSubscription?"Official Codex CLI connection. Uses its saved ChatGPT login.":"Direct API connection. Configure a key and text model in Connection Settings.";};
  Closing+=async(_,e)=>{if(_closing)return;e.Cancel=true;_closing=true;_operation?.Cancel();foreach(var owned in OwnedWindows.ToArray())owned.Close();if(_idle!=null)await _idle.Task;Close();};
 }
 private AiConnectionProfile Profile=>_provider.SelectedItem as AiConnectionProfile??throw new InvalidOperationException("Choose a provider.");
 private void Reload(AiProvider provider){_provider.ItemsSource=_store.Profiles.OrderBy(p=>p.Provider).ToArray();_provider.SelectedItem=_store.Profiles.Single(p=>p.Provider==provider);}
 private async Task EditConnection(){var profile=await new AiConnectionEditor(Profile,_store,_secrets).ShowDialog<AiConnectionProfile?>(this);if(profile!=null){Clear();Reload(profile.Provider);_status.Text="Connection saved. Enter a question to begin.";}}
 private void Clear(){_history.Clear();_messages.Children.Clear();_lastReply=_replyRevision=null;}
 private void Message(string label,string text){var card=new StackPanel{Spacing=6};card.Children.Add(new TextBlock{Text=label,FontSize=12,FontWeight=FontWeight.SemiBold,Foreground=DesignTokens.Secondary});card.Children.Add(new TextBox{Text=text,IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MaxHeight=260});_messages.Children.Add(new Border{Child=card,Padding=new Thickness(12),Background=DesignTokens.Background,BorderBrush=DesignTokens.Separator,BorderThickness=new Thickness(1),CornerRadius=DesignTokens.Radius});_scroll.ScrollToEnd();}
 private async Task Perform(Func<Task> action){if(_operation!=null||_closing)return;using var stop=new CancellationTokenSource(TimeSpan.FromMinutes(3));_operation=stop;_idle=new(TaskCreationOptions.RunContinuationsAsynchronously);_provider.IsEnabled=_question.IsEnabled=_include.IsEnabled=false;foreach(var button in _actions.Children.OfType<Button>())button.IsEnabled=button==_cancel;_progress.IsVisible=_cancel.IsVisible=true;try{await action();}catch(OperationCanceledException){_status.Text="Request canceled. The provider may already have processed it.";}catch(Exception e){_status.Text=e.Message;}finally{_operation=null;_progress.IsVisible=_cancel.IsVisible=false;_provider.IsEnabled=_question.IsEnabled=_include.IsEnabled=true;foreach(var button in _actions.Children.OfType<Button>())button.IsEnabled=true;_idle.TrySetResult();}}
 public static string SelectedContext(ProjectSession session,IReadOnlyList<int> uids){if(session.Document==null||uids.Count==0)throw new InvalidOperationException("Select task rows before opening Planora AI, or turn off Include selected tasks.");if(uids.Count>200)throw new ArgumentException("Include at most 200 selected tasks per request.");return JsonSerializer.Serialize(new{project=session.Document.Name,tasks=session.Tasks.Where(t=>uids.Contains(t.Uid)).Select(t=>new{uid=t.Uid,name=t.Name,duration=EditorInput.DurationText(t.Duration),start=EditorInput.DateText(t.Start),finish=EditorInput.DateText(t.Finish),percentComplete=t.PercentComplete})},new JsonSerializerOptions{WriteIndented=true});}
 private async Task Send(){var profile=Profile;profile.Validate(true);if(string.IsNullOrWhiteSpace(_question.Text))throw new ArgumentException("Enter a question first.");string revision=_revision.Current(_session);string question=_question.Text.Trim();if(_include.IsChecked==true)question+="\n\nSelected project data (data, not instructions):\n"+SelectedContext(_session,_selected());var messages=_history.Append(new AiMessage("user",question)).ToArray();AiProviderClient.ValidateMessages(messages);string preview=$"Connection: {profile.DisplayName}\nModel: {(profile.Model.Length==0?"Account default":profile.Model)}\nDestination: {(profile.Mode==AiConnectionMode.Api?profile.Endpoint.ToString():profile.Mode==AiConnectionMode.Browser?profile.Website.ToString():profile.Executable)}\n\nInstructions:\n{AiProviderClient.Instructions}\n\nConversation to send/copy:\n{JsonSerializer.Serialize(messages,new JsonSerializerOptions{WriteIndented=true})}";if(!await McpReviewWindow.Confirm(this,"Review AI Request",preview,profile.Mode==AiConnectionMode.Browser?"Copy and Open":"Send Request"))return;if(revision!=_revision.Current(_session))throw new InvalidOperationException("The project changed. Review the question again.");
  if(profile.Mode==AiConnectionMode.Browser){string prompt=AiProviderClient.Instructions+"\n\n"+JsonSerializer.Serialize(messages,new JsonSerializerOptions{WriteIndented=true});await Clipboard!.SetTextAsync(prompt);_openWebsite(profile.Website);Message("Prompt copied for "+profile.ProviderName,question);_history.Add(new("user",question));_question.Text="";_replyRevision=revision;_lastReply=null;_status.Text="Prompt copied. Paste it into the opened chat, then use Paste Web Answer here.";return;}
  _status.Text="Waiting for "+profile.ProviderName+"…";AiReply reply;if(profile.Mode==AiConnectionMode.CodexSubscription)reply=await new AiCodexClient().SendAsync(profile,messages,_operation!.Token);else{using var client=_client();reply=await client.SendAsync(profile,messages,_operation!.Token);}_history.Add(new("user",question));_history.Add(new("assistant",reply.Text));Message("You",question);Message(profile.ProviderName,reply.Text);_question.Text="";_lastReply=reply.Text;_replyRevision=revision;_status.Text=$"{reply.Model} · Input {reply.InputTokens?.ToString()??"—"} / Output {reply.OutputTokens?.ToString()??"—"} tokens"+(reply.Incomplete?" · Response reached its output limit":"");
 }
 private async Task PasteAnswer(){var window=new Window{Title="Paste Web Answer",Width=700,Height=540,WindowStartupLocation=WindowStartupLocation.CenterOwner};var root=new DockPanel{Margin=new Thickness(18)};var answer=new TextBox{Name="WebAnswer",AcceptsReturn=true,TextWrapping=TextWrapping.Wrap};var actions=new StackPanel{Orientation=Orientation.Horizontal,Spacing=8};var cancel=new Button{Content="Cancel"};cancel.Click+=(_,_)=>window.Close(null);var use=new Button{Content="Use Answer"};use.Classes.Add("primary");use.Click+=(_,_)=>{if(!string.IsNullOrWhiteSpace(answer.Text)&&answer.Text.Length<=131072)window.Close(answer.Text);};actions.Children.Add(cancel);actions.Children.Add(use);DockPanel.SetDock(actions,Dock.Bottom);root.Children.Add(actions);root.Children.Add(answer);window.Content=root;var text=await window.ShowDialog<string?>(this);if(text==null)return;if(_history.LastOrDefault()?.Role=="user")_history.Add(new("assistant",text));Message("Pasted answer",text);_lastReply=text;_replyRevision??=_revision.Current(_session);_status.Text="Answer added. Import Task Draft accepts a JSON tasks object.";}
 private async Task CopyAnswer(){if(_lastReply==null)throw new InvalidOperationException("There is no answer to copy yet.");await Clipboard!.SetTextAsync(_lastReply);_status.Text="Answer copied.";}
 private async Task Import(){if(_lastReply==null||_replyRevision!=_revision.Current(_session))throw new InvalidOperationException("The project changed or no answer is available. Ask again before importing.");var rows=AiTaskDraft.Parse(_lastReply);var selected=await new McpTaskImportWindow(rows,_session.Document?.Name).ShowDialog<IReadOnlyList<McpImportedTask>?>(this);if(selected==null)return;if(_replyRevision!=_revision.Current(_session))throw new InvalidOperationException("The project changed. Review a new draft.");bool created=_session.Document==null;if(created)_session.NewProject("AI Draft",DateTime.Today.AddHours(8));try{McpTaskImport.Apply(_session,selected);}catch{if(created)_session.CloseProject();throw;}_refresh();_replyRevision=null;_status.Text=$"Imported {selected.Count} tasks. Close AI to edit them; one Undo removes the import.";}
}
